import json
import sys
from collections import deque

def is_passable_b1f(x, y):
    # Passable coordinates on B1F (Map 0_232)
    # Row 16-19 bypass corridor
    if y in [16, 17, 18, 19] and 20 <= x <= 29:
        return True
    # Row 20-24 Western vertical/horizontal corridor
    if y in [20, 21, 22, 23, 24] and 20 <= x <= 25:
        return True
    # Row 25-27 Western corridor
    if y in [25, 26, 27] and 14 <= x <= 25:
        return True
    # Starting chamber (Columns 28-37, Rows 21-29)
    if y in [21, 22, 23, 24, 25, 26, 27, 28, 29] and 28 <= x <= 37:
        return True
    # Row 28-29 Western vertical bypass
    if y in [28, 29] and 14 <= x <= 17:
        return True
    # Row 30 passable tiles
    if y == 30 and x in [14, 15, 16, 17, 25, 28, 29]:
        return True
    # Row 31-33 Southern corridor
    if y in [31, 32, 33] and 14 <= x <= 29:
        return True
    # Ladder A
    if x == 33 and y == 25:
        return True
    return False

def is_passable_1f(x, y):
    # Passable coordinates on 1F (Map 0_82)
    if y in [2, 3] and 14 <= x <= 17:
        return True
    if y in [4, 5, 6, 7] and 14 <= x <= 25:
        return True
    if y in [8, 9] and 20 <= x <= 25:
        return True
    if y in [10, 11, 12, 13] and 20 <= x <= 37:
        return True
    if y in [8, 9] and 34 <= x <= 37:
        return True
    if x == 17 and y == 11:
        return True
    return False

def get_path(curr_x, curr_y, tgt_x, tgt_y, map_id):
    if map_id == "0_232":
        is_passable = is_passable_b1f
    elif map_id == "0_82":
        is_passable = is_passable_1f
    else:
        return False, [], "Unknown map ID"

    if not is_passable(curr_x, curr_y):
        return False, [], f"Current position ({curr_x}, {curr_y}) is marked as impassable"
    if not is_passable(tgt_x, tgt_y):
        return False, [], f"Target position ({tgt_x}, {tgt_y}) is marked as impassable"

    # BFS setup
    queue = deque([(curr_x, curr_y, [])])
    visited = {(curr_x, curr_y)}

    dirs = [
        (0, 1, "Down", "Up"),
        (0, -1, "Up", "Down"),
        (1, 0, "Right", "Left"),
        (-1, 0, "Left", "Right")
    ]

    while queue:
        x, y, path = queue.popleft()
        if x == tgt_x and y == tgt_y:
            backtrack = []
            for d in reversed(path):
                if d == "Up": backtrack.append("Down")
                elif d == "Down": backtrack.append("Up")
                elif d == "Left": backtrack.append("Right")
                elif d == "Right": backtrack.append("Left")
            return True, path, backtrack

        for dx, dy, btn, rev in dirs:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in visited and is_passable(nx, ny):
                visited.add((nx, ny))
                queue.append((nx, ny, path + [btn]))

    return False, [], "No path found"

try:
    curr_x = int(input_data['current_x'])
    curr_y = int(input_data['current_y'])
    tgt_x = int(input_data['target_x'])
    tgt_y = int(input_data['target_y'])
    map_id = input_data['map_id']

    found, path, backtrack = get_path(curr_x, curr_y, tgt_x, tgt_y, map_id)
    if found:
        response = {
            "path_found": True,
            "buttons": path,
            "backtrack_buttons": backtrack,
            "reasoning": f"Path found from ({curr_x}, {curr_y}) to ({tgt_x}, {tgt_y}) using updated passable coordinate set on map {map_id}."
        }
    else:
        response = {
            "path_found": False,
            "buttons": [],
            "backtrack_buttons": [],
            "reasoning": f"No path found: {backtrack}"
        }
    print(json.dumps(response))
except Exception as e:
    print(json.dumps({"path_found": False, "buttons": [], "backtrack_buttons": [], "reasoning": f"Error: {str(e)}"}))
